t.script:
                (() => {
                    const map = L.map('courier-map').setView([46.4825, 30.7233], 11);
                    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                        maxZoom: 19,
                        attribution: '&copy; OpenStreetMap contributors'
                    }).addTo(map);

                    const rpcPayload = {
                        jsonrpc: '2.0',
                        method: 'call',
                        params: {}
                    };

                    fetch('/courier/map/data', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify(rpcPayload)
                    })
                    .then(response => response.json())
                    .then(payload => {
                        const data = payload.result || {};

                        (data.zones || []).forEach((zone) => {
                            if (!zone.polygon || !zone.polygon.length) {
                                return;
                            }
                            const latlngs = zone.polygon.map((point) => [point[1], point[0]]);
                            L.polygon(latlngs, {
                                color: zone.color || '#1f6feb',
                                fillOpacity: 0.08,
                            }).bindPopup(zone.name).addTo(map);
                        });

                        (data.lines || []).forEach((line) => {
                            if (!line.coordinates || !line.coordinates.length) {
                                return;
                            }
                            const latlngs = line.coordinates.map((point) => [point[1], point[0]]);
                            L.polyline(latlngs, {
                                color: '#ff7b00',
                                weight: 4,
                                opacity: 0.8,
                            }).bindPopup(`${line.name} (${line.state})`).addTo(map);
                        });

                        (data.stops || []).forEach((stop) => {
                            L.circleMarker([stop.lat, stop.lon], {
                                radius: 6,
                                color: stop.status === 'delivered' ? '#2da44e' : '#d1242f',
                                fillOpacity: 0.8,
                            }).bindPopup(`${stop.name}
${stop.route}`).addTo(map);
                        });
                    })
                    .catch(() => {
                        L.popup()
                            .setLatLng([46.4825, 30.7233])
                            .setContent('Cannot load courier map data.')
                            .openOn(map);
                    });
                })();
